package br.com.sistemacardapio.pedido;
import java.io.IOException;import java.util.*;import java.util.concurrent.*;import org.springframework.stereotype.Service;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@Service public class PedidoEventoService{private final Map<UUID,List<SseEmitter>> clientes=new ConcurrentHashMap<>();public SseEmitter conectar(UUID empresa){SseEmitter e=new SseEmitter(0L);clientes.computeIfAbsent(empresa,x->new CopyOnWriteArrayList<>()).add(e);e.onCompletion(()->remover(empresa,e));e.onTimeout(()->remover(empresa,e));try{e.send(SseEmitter.event().name("conectado").data("ok"));}catch(IOException ex){remover(empresa,e);}return e;}public void publicar(UUID empresa,String tipo,Object dado){for(SseEmitter e:clientes.getOrDefault(empresa,List.of()))try{e.send(SseEmitter.event().name(tipo).data(dado));}catch(Exception ex){remover(empresa,e);}}private void remover(UUID id,SseEmitter e){clientes.getOrDefault(id,List.of()).remove(e);}}
